# Paste into Azure Cloud Shell (Bash). Creates the free B2ats_v2 server in Korea Central,
# reusing the existing tejaskrit_key.pem (only its public half is here).
az group create -n tejaskrit-kr -l koreacentral -o none && az vm create -g tejaskrit-kr -n tejaskrit -l koreacentral   --image Canonical:ubuntu-24_04-lts:server:latest --size Standard_B2ats_v2 --security-type Standard   --admin-username azureuser --ssh-key-values "ssh-rsa "   --public-ip-sku Standard --public-ip-address-dns-name tejaskrit-rishabh   --os-disk-size-gb 64 --storage-sku Premium_LRS --nsg-rule SSH -o table && az vm open-port -g tejaskrit-kr -n tejaskrit --port 80,443 --priority 1010 -o none && echo "READY: tejaskrit-rishabh.koreacentral.cloudapp.azure.com"
